{
  "findings": [
    {
      "check_id": "CKV_AZURE_52",
      "title": "MSSQL minimum TLS version is not configured",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "The server does not set minimum_tls_version, so it does not explicitly enforce TLS 1.2 for client connections."
    },
    {
      "check_id": "CKV2_AZURE_27",
      "title": "Azure AD authentication is not enabled for MSSQL",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "No Azure AD administrator is configured, preventing the server from using centrally managed Azure AD identities for authentication."
    },
    {
      "check_id": "CKV_AZURE_26",
      "title": "MSSQL security alert recipients are not configured",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "The file has no MSSQL security alert policy with recipient email addresses, so relevant database threat alerts may not reach responders."
    },
    {
      "check_id": "CKV_AZURE_27",
      "title": "MSSQL service and co-administrator alerts are not enabled",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "The file has no security alert policy enabling notifications to subscription service administrators and co-administrators."
    }
  ],
  "patched_code": "variable "mssql_azuread_administrator_login_username" {
  description = "Login name of the Azure AD principal that will administer the MSSQL server."
  type        = string

  validation {
    condition     = length(trimspace(var.mssql_azuread_administrator_login_username)) > 0
    error_message = "The Azure AD administrator login username must not be empty."
  }
}

variable "mssql_azuread_administrator_object_id" {
  description = "Object ID of the Azure AD principal that will administer the MSSQL server."
  type        = string

  validation {
    condition     = length(trimspace(var.mssql_azuread_administrator_object_id)) > 0
    error_message = "The Azure AD administrator object ID must not be empty."
  }
}

variable "mssql_azuread_tenant_id" {
  description = "Tenant ID containing the Azure AD administrator principal."
  type        = string

  validation {
    condition     = length(trimspace(var.mssql_azuread_tenant_id)) > 0
    error_message = "The Azure AD tenant ID must not be empty."
  }
}

variable "mssql_security_alert_email_addresses" {
  description = "Email addresses that receive MSSQL security alerts."
  type        = set(string)

  validation {
    condition = length(var.mssql_security_alert_email_addresses) > 0 && alltrue([
      for address in var.mssql_security_alert_email_addresses : length(trimspace(address)) > 0
    ])
    error_message = "At least one non-empty MSSQL security alert email address must be provided."
  }
}

resource "azurerm_mssql_server" "changeme_simple_mssql_server" {
  name                = "changeme-simple-mssql-database-name"
  resource_group_name = azurerm_resource_group.changeme_simple_mssql_server_resource_group.name
  location            = azurerm_resource_group.changeme_simple_mssql_server_resource_group.location
  version             = "12.0"
  minimum_tls_version = "1.2"

  administrator_login          = "changemeadmin"
  administrator_login_password = "ch4ng3m3-A@Â£$%^&"

  azuread_administrator {
    login_username = var.mssql_azuread_administrator_login_username
    object_id      = var.mssql_azuread_administrator_object_id
    tenant_id      = var.mssql_azuread_tenant_id
  }
}

resource "azurerm_mssql_server_security_alert_policy" "changeme_simple_mssql_server" {
  resource_group_name  = azurerm_mssql_server.changeme_simple_mssql_server.resource_group_name
  server_name          = azurerm_mssql_server.changeme_simple_mssql_server.name
  state                = "Enabled"
  email_account_admins = true
  email_addresses      = var.mssql_security_alert_email_addresses
}
",
  "fix_summary": "Enforced TLS 1.2, added a configurable Azure AD administrator, and enabled MSSQL security alerts for both supplied recipients and account administrators. Required identity and email values are exposed as validated input variables rather than placeholders."
}
